 async function play(force=false){if(muted||document.hidden)return;if(!force&&(pending?.dataset.track===current||active?.dataset.track===current&&!active.paused))return;const token=++serial;cancelFade();dispose(pending);pending=null; const bed=document.getElementById('opening-score');const reuse=bed&&current==='world'&&bed.dataset.consumed!=='1';const next=reuse?bed:(cache[current]||new Audio());delete cache[current];next.dataset.track=current;if(!reuse)next.src='assets/audio/'+current+'.mp3?v=101';next.preload='auto';next.loop=true; if(reuse&&!next.paused){bed.dataset.consumed='1';blocked=false;active=next;pending=null;next.volume=volume;ui();return}const previous=active;next.volume=previous?0:volume;try{if(force||previous)next.currentTime=force?0:(positions[current]||0)}catch{}pending=next;

 try{await next.play();if(token!==serial){if(pending===next)pending=null;return}if(muted){if(pending===next)pending=null;if(next.id==='opening-score')next.pause();else dispose(next);return}blocked=false;if(next.id==='opening-score')next.dataset.consumed='1';active=next;pending=null;next.volume=previous?next.volume:volume;if(previous)crossfade(next,previous);ui()}catch{if(token!==serial||pending!==next){if(pending===next)pending=null;return}pending=null;if(next.id==='opening-score')next.pause();else dispose(next);blocked=true;ui()}}
 button.onclick=e=>{e.stopPropagation();if(blocked){muted=false;localStorage.setItem('world-music-muted','false');play(true);return}muted=!muted;localStorage.setItem('world-music-muted',String(muted));if(muted){serial++;dispose(pending);pending=null;const old=active;active=null;crossfade(null,old,650)}else play();ui()};
 function unlock(){if(!muted)play()}
