 const bed=document.getElementById('opening-score');
 function adoptBed(){if(!bed||muted||bed.paused)return;blocked=false;active=bed;bed.dataset.track=bed.dataset.track||'world';bed.dataset.consumed='1';bed.loop=true;bed.volume=volume;ui()}
 bed?.addEventListener('playing',adoptBed);
 ui();if(!muted)play();adoptBed();return{destination(id){const next=requestedScoreTracks[id]?id:'world';if(next===current)return;current=next;ui();play()},preload,paper(){}};
